import sys

def can_transform(A, B, R, C, X):
    def check_differences(diff):
        for i in range(R):
            for j in range(C - X + 1):
                if diff[i][j] != diff[i][j + 1]:
                    return False
        for j in range(C):
            for i in range(R - X + 1):
                if diff[i][j] != diff[1 + i][j]:
                    return False
        return True

    diff = [[B[i][j] - A[i][j] for j in range(C)] for i in range(R)]
    return check_differences(diff)

input = sys.stdin.read().split()
index = 0
T = int(input[index])
index += 1
results = []

for _ in range(T):
    R = int(input[index])
    C = int(input[index + 1])
    X = int(input[index + 2])
    index += 3
    A = []
    for _ in range(R):
        A.append(list(map(int, input[index:index + C])))
        index += C
    B = []
    for _ in range(R):
        B.append(list(map(int, input[index:index + C])))
        index += C

    result = "Yes" if can_transform(A, B, R, C, X) else "No"
    results.append(result)

print("\n".join(results))
